PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS phors_competitions (id INTEGER PRIMARY KEY AUTOINCREMENT, source_key TEXT NOT NULL UNIQUE, name TEXT NOT NULL, source_url TEXT NOT NULL, source_host TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS phors_exams (id INTEGER PRIMARY KEY AUTOINCREMENT, competition_id INTEGER NOT NULL REFERENCES phors_competitions(id) ON DELETE CASCADE, source_key TEXT NOT NULL, source_url TEXT NOT NULL UNIQUE, title TEXT NOT NULL, year INTEGER, code TEXT, series TEXT CHECK (series IS NULL OR series IN ('W','X','Y')), source_hash TEXT NOT NULL, imported_at TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS phors_exams_competition_idx ON phors_exams(competition_id);
CREATE TABLE IF NOT EXISTS phors_problems (id INTEGER PRIMARY KEY AUTOINCREMENT, exam_id INTEGER NOT NULL REFERENCES phors_exams(id) ON DELETE CASCADE, source_id TEXT NOT NULL UNIQUE, source_url TEXT NOT NULL UNIQUE, code TEXT, title TEXT NOT NULL, kind TEXT NOT NULL DEFAULT 'unknown' CHECK (kind IN ('theoretical','experimental','unknown')), statement_url TEXT, solution_url TEXT, marking_scheme_url TEXT, statement_pdf_url TEXT, solution_pdf_url TEXT, attachments_json TEXT NOT NULL DEFAULT '[]', parts_status TEXT NOT NULL DEFAULT 'not_fetched' CHECK (parts_status IN ('structured','not_available','not_fetched')), source_hash TEXT NOT NULL, imported_at TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS phors_problems_exam_idx ON phors_problems(exam_id);
CREATE TABLE IF NOT EXISTS phors_problem_parts (id INTEGER PRIMARY KEY AUTOINCREMENT, problem_id INTEGER NOT NULL REFERENCES phors_problems(id) ON DELETE CASCADE, source_key TEXT NOT NULL, code TEXT NOT NULL, parent_code TEXT, ordinal INTEGER NOT NULL, score REAL, score_reliability TEXT CHECK (score_reliability IS NULL OR score_reliability = 'explicit_html'), prompt_text TEXT, source_url TEXT NOT NULL, UNIQUE(problem_id, source_key));
CREATE INDEX IF NOT EXISTS phors_problem_parts_problem_idx ON phors_problem_parts(problem_id);
CREATE TABLE IF NOT EXISTS phors_tags (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, normalized_name TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS phors_problem_tags (problem_id INTEGER NOT NULL REFERENCES phors_problems(id) ON DELETE CASCADE, tag_id INTEGER NOT NULL REFERENCES phors_tags(id) ON DELETE CASCADE, PRIMARY KEY(problem_id, tag_id));
CREATE INDEX IF NOT EXISTS phors_problem_tags_tag_idx ON phors_problem_tags(tag_id);
CREATE TABLE IF NOT EXISTS phors_sync_runs (id INTEGER PRIMARY KEY AUTOINCREMENT, started_at TEXT NOT NULL, finished_at TEXT, status TEXT NOT NULL DEFAULT 'running' CHECK (status IN ('running','succeeded','failed')), exam_urls_json TEXT NOT NULL, stats_json TEXT NOT NULL DEFAULT '{}', error_text TEXT);
